std::vector<Adhesion::Node> nodes;
nodes.reserve(rt.number_of_vertices());

for (auto vit = rt.finite_vertices_begin(); vit != rt.finite_vertices_end(); ++vit) {
    Adhesion::Node node;
    auto point = vit->point();
    node.position = {point.x(), point.y(), point.z()};

    auto cell = vit->cell();
    node.velocity = {velocity(cell)[0], velocity(cell)[1], velocity(cell)[2]};

    // Calculate mass (volume of Voronoi cell)
    double mass = 0.0;
    auto rc = rt.incident_cells(vit);
    auto rc_end = rc;
    do {
        if (rt.is_infinite(rc)) continue;
        mass += rt.dual(rc);
    } while (++rc != rc_end);
    node.mass = mass;

    // Classify node type
    int edges = edge_count(cell, threshold);
    node.node_type = type_from_edge_count(edges);

    nodes.push_back(node);
}

return nodes;

